package com.my.project;
import com.mailjet.client.errors.MailjetException;
import com.mailjet.client.errors.MailjetSocketTimeoutException;
import com.mailjet.client.MailjetClient;
import com.mailjet.client.MailjetRequest;
import com.mailjet.client.MailjetResponse;
import com.mailjet.client.ClientOptions;
import com.mailjet.client.resource.Emailv31;
import org.json.JSONArray;
import org.json.JSONObject;
public class MyClass {
    public static void main(String[] args) throws MailjetException, MailjetSocketTimeoutException {
      MailjetClient client;
      MailjetRequest request;
      MailjetResponse response;
      client = new MailjetClient(System.getenv("MJ_APIKEY_PUBLIC"), System.getenv("MJ_APIKEY_PRIVATE"), new ClientOptions("v3.1"));
      request = new MailjetRequest(Emailv31.resource)
            .property(Emailv31.SANDBOXMODE, true)
            .property(Emailv31.MESSAGES, new JSONArray()
                .put(new JSONObject()
                    .put(Emailv31.Message.FROM, new JSONObject()
                        .put("Email", "pilot@mailjet.com")
                        .put("Name", "Your Mailjet Pilot")
                    )
                    .put("HTMLPart", "<h3>Dear passenger, welcome to Mailjet!</h3><br />May the delivery force be with you!")
                    .put("Subject", "Your email flight plan!")
                    .put("TextPart", "Dear passenger, welcome to Mailjet! May the delivery force be with you!")
                    .put(Emailv31.Message.TO, new JSONArray()
                        .put(new JSONObject()
                            .put("Email", "passenger@mailjet.com")
                            .put("Name", "Passenger 1")
                        )
                    )
                    )
            )
      );
      response = client.post(request);
      System.out.println(response.getStatus());
      System.out.println(response.getData());
    }
}

using Mailjet.Client;
using Mailjet.Client.Resources;
using System;
using Newtonsoft.Json.Linq;
namespace Mailjet.ConsoleApplication
{
   class Program
   {
      static void Main(string[] args)
      {
         RunAsync().Wait();
      }
      static async Task RunAsync()
      {
         MailjetClient client = new MailjetClient(Environment.GetEnvironmentVariable("MJ_APIKEY_PUBLIC"), Environment.GetEnvironmentVariable("MJ_APIKEY_PRIVATE"))
         {
            Version = ApiVersion.V3_1,
         };
         MailjetRequest request = new MailjetRequest
         {
            Resource = Send.Resource,
         }
             .Property(Send.SandboxMode, true)
             .Property(Send.Messages, new JArray {
                 new JObject {
                     {"From", new JObject {
                         {"Email", "pilot@mailjet.com"},
                         {"Name", "Your Mailjet Pilot"}
                     }},
                     {"HTMLPart", "<h3>Dear passenger, welcome to Mailjet!</h3><br />May the delivery force be with you!"},
                     {"Subject", "Your email flight plan!"},
                     {"TextPart", "Dear passenger, welcome to Mailjet! May the delivery force be with you!"},
                     {"To", new JArray {
                         new JObject {
                             {"Email", "passenger@mailjet.com"},
                             {"Name", "Passenger 1"}
                         }
                     }}
                 }
             });
         MailjetResponse response = await client.PostAsync(request);
         if (response.IsSuccessStatusCode)
         {
            Console.WriteLine(string.Format("Total: {0}, Count: {1}\n", response.GetTotal(), response.GetCount()));
            Console.WriteLine(response.GetData());
         }
         else
         {
            Console.WriteLine(string.Format("StatusCode: {0}\n", response.StatusCode));
            Console.WriteLine(string.Format("ErrorInfo: {0}\n", response.GetErrorInfo()));
            Console.WriteLine(response.GetData());
            Console.WriteLine(string.Format("ErrorMessage: {0}\n", response.GetErrorMessage()));
         }
      }
   }
}

